    {
        FinancingCategories: {
            Equity: LookUp(
                colFinancingCategories,
                Order = 1
            ),
            VATFinancing: LookUp(
                colFinancingCategories,
                Order = 2
            ),
            SeniorDebt: LookUp(
                colFinancingCategories,
                Order = 3
            ),
            Decommissioning: LookUp(
                colFinancingCategories,
                Order = 5
            ),
            DSRA_DSRF: LookUp(
                colFinancingCategories,
                Order = 4
            ),
            CashSweep: LookUp(
                colFinancingCategories,
                Order = 6
            )
        }
    }
);
