    ClearCollect(
        colFinancingInputInProject,
        Filter(
            'Financing Inputs',
            Project.Project = gblRecordSelectedProject.Project
        )
    ),
    ClearCollect(
        colFinanceCategoriesInProject,
        AddColumns(
            colFinancingCategories,
            IsFolded,
            true
        )
    ),
    ClearCollect(
        colStandardAssumptionsDebt,
        Filter(
            'Assumptions Debt SQL',
            country = gblRecordSelectedProjectCountry.Name,
            debttype = "debt facility"
        )
    );
    Collect(
        colStandardAssumptionsDebt,
        Filter(
            'Assumptions Debt SQL',
            country = gblRecordSelectedProjectCountry.Name,
            debttype = "DSCR"
        )
    );
    ClearCollect(
        colStandardAssumptionsDecommissioning,
        Filter(
            'Assumptions Debt SQL',
            country = gblRecordSelectedProjectCountry.Name,
            debttype = "decommissioning costs"
        )
    );
    ClearCollect(
        colStandardAssumptionsDSRA_DSRF,
        Filter(
            'Assumptions Debt SQL',
            country = gblRecordSelectedProjectCountry.Name,
            debttype in [
                "DSRA_DSRF",
                "DSRA",
                "DSRF"
