                {
                    Status: If(
                        locDSRA_DSRFFinancingInput.'DSRA/DSRF Original Status Active?' = 'DSRA/DSRF Original Status Active? (Financing Inputs)'.Yes,
                        'Status (Financing Inputs)'.Active,
                        'Status (Financing Inputs)'.Inactive
                    )
                }
            )
    );

);
