Table(
    {
        ItemKey: "AddFinanceInput",
        ItemDisplayName: "Add Tranche",
        ItemIconName: "Add",
        ItemEnabled: And(
            DataSourceInfo(
                'Financing Inputs',
                DataSourceInfo.CreatePermission
            ),
            With(
                {
                    locSeniorDebtInputs: Filter(
                        colFinancingInputInProject,
                        'Financing Category'.'Financing Category' = LookUp(
                            colFinancingCategories,
                            Order = 3,
                            'Financing Category'
                        )
                    )
                },
                Not(
                    And(
                        CountIf(
                            locSeniorDebtInputs,
                            'Tranche Status' = 'Senior Debt Tranche Status '.'Standard Assumption'
                        ) = 1,
                        CountIf(
                            locSeniorDebtInputs,
                            true
                        ) = 1
                    )
                )
            )
        )
    },
    {
        ItemKey: "EditFinanceInput",
        ItemDisplayName: "Edit Tranche",
        ItemIconName: "Edit",
        ItemEnabled: And(
            Not(IsBlank(locSelectedSeniorDebtTranche)),
            RecordInfo(
                locSelectedSeniorDebtTranche,
                DataSourceInfo.EditPermission
            ),locSelectedSeniorDebtTranche.Status='Status (Financing Inputs)'.Active
        )
    },
    {
        ItemKey: "ActivateFinanceInput",
        ItemDisplayName: "Activate Tranche",
        ItemIconName: "ActivateOrders",
        ItemVisible: And(
            Not(IsBlank(locSelectedSeniorDebtTranche)),
            locSelectedSeniorDebtTranche.Status = 'Status (Financing Inputs)'.Inactive
        ),
        ItemEnabled: And(
            Not(IsBlank(locSelectedSeniorDebtTranche)),
            RecordInfo(
                locSelectedSeniorDebtTranche,
                RecordInfo.EditPermission
            )
            //,Not(locSelectedSeniorDebtTranche.'Tranche Status' = 'Senior Debt Tranche Status '.'Credit Agreement')
        )
    },
    {
        ItemKey: "DeactivateFinanceInput",
        ItemDisplayName: "Deactivate Tranche",
        ItemIconName: "DeactivateOrders",
        ItemVisible: And(
            Not(IsBlank(locSelectedSeniorDebtTranche)),
            locSelectedSeniorDebtTranche.Status = 'Status (Financing Inputs)'.Active
        ),
        ItemEnabled: And(
            Not(IsBlank(locSelectedSeniorDebtTranche)),
            RecordInfo(
                locSelectedSeniorDebtTranche,
                RecordInfo.EditPermission
            ),
           // Not(locSelectedSeniorDebtTranche.'Tranche Status' = 'Senior Debt Tranche Status '.'Credit Agreement'),
            CountIf(
                colFinancingInputInProject,
                'Financing Category'.'Financing Category' = LookUp(
                    colFinancingCategories,
                    Order = 3
                ).'Financing Category',
                Status = 'Status (Financing Inputs)'.Active
            )>1
        )
    },
    {
        ItemKey: "DeleteFinancingInput",
        ItemDisplayName: "Delete",
        ItemIconName: "Delete",
        ItemVisible: true,
        ItemEnabled: And(
            Not(IsBlank(locSelectedSeniorDebtTranche)),
            RecordInfo(
                locSelectedSeniorDebtTranche,
                RecordInfo.DeletePermission
            ),
            Not(locSelectedSeniorDebtTranche.'Tranche Status' = 'Senior Debt Tranche Status '.'Credit Agreement'),
            Not(locSelectedSeniorDebtTranche.'Tranche Status' = 'Senior Debt Tranche Status '.'Standard Assumption'),
            With(
                {
                    locSeniorDebtInputs: Filter(
                        colFinancingInputInProject,
                        'Financing Category'.'Financing Category' = LookUp(
                            colFinancingCategories,
                            Order = 3,
                            'Financing Category'
                        )
                    )
                },
                Not(
                    CountIf(
                        locSeniorDebtInputs,
                        true
                    ) = 1
                )
            )
        )
    }
)

Switch(
    Text(Self.Selected.ItemKey),
    "AddFinanceInput",
    Select(btn_GeneralData_RightPanel_SeniorDebt_Form_Button_Reset_1);
    Clear(colRepaymentProfileAmount);
    Clear(colStepUpBankMargins);
    UpdateContext(
        {
            locIsVisibleRightPanelSeniorDebtForm: true,
            locSelectedSeniorDebtTranche: Blank(),
            locSelectedTrancheStatus: [],
            locSelectedFixedAmount: [],
            locSelectedCommitmentFee: [],
            locSelectedStandardAssumption: locStandardAssumptionForSeniorDebt2,
            locFormIsDirty: true,
            locTempSelectedSeniorDebtTranche: Blank(),
            locCheckForStandardAssumption: Blank(),
            locUpfrontFee: locStandardAssumptionForSeniorDebt2.'Upfront Fee Value',
            locCommitmentFee: locStandardAssumptionForSeniorDebt2.'Commitment Fee Value',
            locFixedAmount: Blank()
        }
    );
    ,
    "EditFinanceInput",
    UpdateContext(
        {
            locSelectedSeniorDebtTranche: LookUp(
                'Financing Inputs',
                'Financing Input' = locSelectedSeniorDebtTranche.'Financing Input'
            )
        }
    );
    UpdateContext(
        {
            locIsVisibleRightPanelSeniorDebtForm: true,
            locSelectedTrancheStatus: [locSelectedSeniorDebtTranche.'Tranche Status'],
            locSelectedFixedAmount: [locSelectedSeniorDebtTranche.'Fixed Amount '],
            locSelectedCommitmentFee: [locSelectedSeniorDebtTranche.'Commitment Fee'],
            locCheckForStandardAssumption: locSelectedSeniorDebtTranche,
            locTempSelectedSeniorDebtTranche: LookUp(
                colFinancingInputInProject,
                'Financing Input' = locSelectedSeniorDebtTranche.'Financing Input'
            ),
            locUpfrontFee: locSelectedSeniorDebtTranche.'Upfront Fee Value',
            locCommitmentFee: locSelectedSeniorDebtTranche.'Commitment Fee Value',
            locFixedAmount: locSelectedSeniorDebtTranche.'Fixed Amount Value',
            locIsFinancialCloseDateStandard: Boolean(First(ParseJSON(locSelectedSeniorDebtTranche.'Senior Debt Standard Assumption JSON')).FinancialCloseDate),
            locFinancialCloseToShow: locSelectedSeniorDebtTranche.'Financial Close'
        }
    );
    Concurrent(
        ClearCollect(
            colRepaymentProfileAmount,
            ForAll(
                Filter(
                    colRepaymentAmountInProject,
                    'Financing Input'.'Financing Input' = locSelectedSeniorDebtTranche.'Financing Input'
                ) As Item,
                {
                    RepaymentAmountRecord: Item,
                    Year: Value(Item.'Repayment Year'),
                    Valid: true,
                    Dirty: false,
                    Value: Text(Item.'Repayment Amount')
                }
            )
        ),
        ClearCollect(
            colStepUpBankMargins,
            ForAll(
                Filter(
                    colStepUpMarginInProject,
                    'Financing Input'.'Financing Input' = locSelectedSeniorDebtTranche.'Financing Input'
                ) As Item,
                {
                    StepUpMarginRecord: Item,
                    Id: Item.Order,
                    Valid: true,
                    StartYear: Item.'Start Year',
                    DurationYY: LookUp(
                        colYearsForDuration,
                        Value = If(
                            Item.Order = 1,
                            (Item.'Start Year' + Item.Duration) - 1,
                            (Item.'Start Year' + Item.Duration)
                        )
                    ),
                    Dirty: true,
                    Margin: Text(Item.'Margin ')
                }
            )
        )
    ),
    "ActivateFinanceInput",
    UpdateContext(
        {
            IsVisibleActivationPanelSeniorDebt: true,
            locSeniorDebtAction: "Activation"
        }
    ),
    "DeactivateFinanceInput",
    UpdateContext(
        {
            IsVisibleActivationPanelSeniorDebt: true,
            locSeniorDebtAction: "Activation"
        }
    ),
    "DeleteFinancingInput",
    UpdateContext(
        {
            IsVisibleActivationPanelSeniorDebt: true,
            locSeniorDebtAction: "Deletion"
        }
    )
);

UpdateContext({locSelectedFinancingInputCategory: ThisItem});
Switch(
    locSelectedFinancingInputCategory.Order,
    1,
    UpdateContext(
        {
            locSelectedFinancingInput: LookUp(
                colFinancingInputInProject,
                'Financing Category'.'Financing Category' = locSelectedFinancingInputCategory.'Financing Category'
            ),
            locIsVisibleRightPanelEquityForm: true
        }
    );
    UpdateContext(
        {
            locFreeEquity: locSelectedFinancingInput.'Free Equity Value',
            locIsStandardFreeEquity: If(
                locIsEquityStandardAssunption.locIsStandardFreeEquity,
                true,
                false
            ),
            locIsStandardShareholderLoan: If(
                locIsEquityStandardAssunption.locIsStandardShareholderLoan,
                true,
                false
            )
        }
    ),
    2,
    UpdateContext(
        {
            locSelectedFinancingInput: LookUp(
                colFinancingInputInProject,
                'Financing Category'.'Financing Category' = locSelectedFinancingInputCategory.'Financing Category'
            ),
            locVatAmount: Blank()
        }
    );
    UpdateContext(
        {
            locVatAmount: locSelectedFinancingInput.'VAT Facility Amount Value',
            locVatFinancingStatndardValues: With(
                {parsed: First(Table(ParseJSON(locSelectedFinancingInput.'Is Standard Value'))).Value},
                {
                    locIsStandardBaseRate: Boolean(parsed.locIsStandardBaseRate),
                    locIsStandardBankMargin: Boolean(parsed.locIsStandardBankMargin)
                }
            )
        }
    );
    If(
        Text(Self.Selected.ItemKey) = "EditFinanceInput",
        UpdateContext({locIsVisibleRightPanelVATFinancingForm: true}),
        UpdateContext({locIsVisibleActivationPanel: true})
    ),
    5,
    If(
        Self.Selected.ItemKey = "ActivateFinanceInput" || Self.Selected.ItemKey = "DeactivateFinanceInput",
        UpdateContext(
            {
                locIsVisibleActivationPanel: true,
                locSelectedFinancingInput: LookUp(
                    colFinancingInputInProject,
                    'Financing Category'.'Financing Category' = ThisItem.'Financing Category'
                )
            }
        ),
        UpdateContext(
            {
