Rules.InvariantScript:
If(
    locIsSavingSeniorDebtTranche,
    false,
    UpdateContext({locIsSavingSeniorDebtTranche: true});
    UpdateContext(
        {
            locIsVisibleRightPanelSeniorDebtForm: false,
            locLoadingSpinnerInformationText: "Please wait, Saving...",
            locIsVisibleLoadingSpinner: true
        }
    );
    With(
        {
            locCurrentSeniorDebtTrancheRecord: If(
                IsBlank(locSelectedSeniorDebtTranche) && Not(IsBlank(locTempSelectedSeniorDebtTranche)),
                locTempSelectedSeniorDebtTranche,
                locSelectedSeniorDebtTranche
            ),
            locSeniorDebtUniqueKeyToSave: With(
                {
                    locTrancheStatusKey: If(
                        rad_SeniorDebt_Data_TrancheStatus.Selected.Value = 'Senior Debt Tranche Status '.'Standard Assumption',
                        "StandardAssumption",
                        Substitute(
                            Lower(Trim(Text(rad_SeniorDebt_Data_TrancheStatus.Selected.Value))),
                            " ",
                            ""
                        )
                    ),
                    locBankKey: If(
                        Lower(Trim(cmb_SeniorDebt_Data_Bank.Selected.bankname)) = "other",
                        "other-" & Substitute(
                            Lower(Trim(txt_SeniorDebtData_BankName.Value)),
                            " ",
                            ""
                        ),
                        "bank-" & Text(cmb_SeniorDebt_Data_Bank.Selected.id)
                    ),
                    locKfWKey: If(
                        tgl_SeniorDebt_Data_KfW_Tranche.Checked,
                        "kfw-" & Substitute(
                            Lower(
                                Trim(
                                    Coalesce(
                                        drp_SeniorDebt_Data_KfW_Tranche_Value.Selected.loantenor_repayfreeperiod_ratefixing,
                                        "blank"
                                    )
                                )
                            ),
                            " ",
                            ""
                        ),
                        "nokfw"
                    )
                },
                If(
                    rad_SeniorDebt_Data_TrancheStatus.Selected.Value = 'Senior Debt Tranche Status '.'Standard Assumption',
                    gblRecordSelectedProject.Project & "-SeniorDebt-StandardAssumption",
                    gblRecordSelectedProject.Project & "-SeniorDebt-" & locTrancheStatusKey & "-" & locBankKey & "-" & locKfWKey
                )
            )
        },
        If(
            !IsBlank(
                LookUp(
                    'Financing Inputs',
                    UniqueKeyString = locSeniorDebtUniqueKeyToSave &&
                    Or(
                        IsBlank(locCurrentSeniorDebtTrancheRecord),
                        'Financing Input' <> locCurrentSeniorDebtTrancheRecord.'Financing Input'
                    )
                )
            ),
            Notify(
                "Same senior debt tranche already exists for this project.",
                NotificationType.Error
            );
            UpdateContext(
                {
                    locIsSavingSeniorDebtTranche: false,
                    locLoadingSpinnerInformationText: "",
                    locIsVisibleLoadingSpinner: false,
                    locIsVisibleRightPanelSeniorDebtForm: false
                }
            );
            Select(btn_GeneralData_RightPanel_SeniorDebt_Form_Button_Reset_1),
            IfError(
                UpdateContext(
                    {
                        locSelectedSeniorDebtTranche: Patch(
                            'Financing Inputs',
                            If(
                                IsBlank(locCurrentSeniorDebtTrancheRecord),
                                Defaults('Financing Inputs'),
                                LookUp(
                                    colFinancingInputInProject,
                                    'Financing Input' = locCurrentSeniorDebtTrancheRecord.'Financing Input'
                                )
                            ),
                            {
                                Name: gblRecordSelectedProject.'Project Name' & " - Senior Debt",
                                Project: gblRecordSelectedProject,
                                'Tranche Status': rad_SeniorDebt_Data_TrancheStatus.Selected.Value,
                                Bank: cmb_SeniorDebt_Data_Bank.Selected.id,
                                'Other Bank Name': If(
                                    Lower(Trim(cmb_SeniorDebt_Data_Bank.Selected.bankname)) = "other",
                                    Trim(txt_SeniorDebtData_BankName.Value),
                                    Blank()
                                ),
                                'KfW Tranche': If(
                                    tgl_SeniorDebt_Data_KfW_Tranche.Checked,
                                    'KfW Tranche (Financing Inputs)'.Yes,
                                    'KfW Tranche (Financing Inputs)'.No
                                ),
                                'KfW-Tranche Value': If(
                                    tgl_SeniorDebt_Data_KfW_Tranche.Checked,
                                    drp_SeniorDebt_Data_KfW_Tranche_Value.Selected.loantenor_repayfreeperiod_ratefixing,
                                    Blank()
                                ),
                                'Financial Close': dte_SeniorDebt_Data_Financial_Close.SelectedDate,
                                'Tenor Duration Month': drp_SeniorDebtData_Tenor_MM.Selected.Value,
                                'Tenor Duration Year': Drp_SeniorDebtData_Tenor_YY.Selected.Value,
                                Drawdown: rad_SeniorDebt_Data_Drawdown.Selected.Value,
                                'DSCR Contracted Decimal': Value(
                                    Left(
                                        Text(txt_SeniorDebt_Data_DSCR_Contracted.Value),
                                        4
                                    )
                                ),
                                'DSCR Uncontracted Decimal': Value(
                                    Left(
                                        Text(txt_SeniorDebtData_DSCR_Uncontracted.Value),
                                        4
                                    )
                                ),
                                'Energy Yield (Debt Sizing)': rad_SeniorDebt_Data_EnergyYield.Selected.Value,
                                'Spot Curve (Debt Sizing)': rad_SeniorDebt_Data_SpotCurve.Selected.Value,
                                Gearing: rad_SeniorDebtData_Gearing.Selected.Value,
                                'Fixed Amount ': rad_SeniorDebt_Fixed_Amount_Options.Selected.Value,
                                'Fixed Amount Value': Value(txt_SeniorDebtData_FixedAmountValue.Value),
                                'Repayment Profile': rad_SeniorDebt_Data_RepaymentProfile.Selected.Value,
                                'Start Repayment (Month)': Drp_SeniorDebtData_StartRepayment_MM.Selected.Value,
                                'Start Repayment (Year)': Drp_SeniorDebtData_StartRepayment_YY.Selected.Value,
                                'Frequency of Repayment': drp_SeniorDebt_Data_Frequency_Of_Repayment.Selected.Value,
                                'Hedging [%]': Value(txt_SeniorDebtData_Hedging.Value),
                                'Upfront Fee': rad_SeniorDebtData_UpfrontFee.Selected.Value,
                                'Upfront Fee Value': Value(txt_SeniorDebtData_UpfrontFeeValue.Value),
                                'Commitment Fee': rad_SeniorDebtData_CommitmentFee.Selected.Value,
                                'Commitment Fee Value': Value(txt_SeniorDebtData_Commitment_Fee_Value.Value),
                                'Commitment Fee Period (Month)': Drp_SeniorDebtData_Commitment_Fee_Free_Period_MM.Selected.Value,
                                'Commitment Fee Period (Year)': Drp_SeniorDebtData_Commitment_Fee_Free_Period_YY.Selected.Value,
                                'Base Rate': rad_SeniorDebtData_BaseRate_2.Selected.Value,
                                'Swap Margin [%]': Value(txt_SeniorDebtData_SwapRate.Value),
                                'Bank Margin - Construction Phase [%]': Value(txt_SeniorDebtData_BankMargin_ConstructionPhase.Value),
                                'Bank Margin - Operational Phase [%]': Value(txt_SeniorDebtData_BankMargin_OperationalPhase.Value),
                                'Fixed Interest Rate (Month)': drp_SeniorDebtData_Fixed_Interest_Rate_MM.Selected.Value,
                                'Fixed Interest Rate (Year)': drp_SeniorDebtData_Fixed_Interest_Rate_YY.Selected.Value,
                                'Step Up Bank Margin': tgl_SeniorDebtData_Step_Up_Bank_Margin.Checked,
                                'Swap After Fixed Period': tgl_SeniorDebt_Data_Swap_After_Fixed_Period.Checked,
                                'Bank Rate': Value(txt_SeniorDebtData_BankMargin.Value),
                                'Swap Rate': Value(txt_SeniorDebtData_SwapMargin.Value),
                                'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)',
                                'Financing Category': LookUp(
                                    colFinancingCategories,
                                    Order = 3
                                ),
                                IsFolded: 'IsFolded (Financing Inputs)'.'true',
                                'Track Status Active?': Coalesce(
                                    locSelectedSeniorDebtTranche.'Track Status Active?',
                                    'Track Status Active? (Financing Inputs)'.Yes
                                ),
                                'Senior Debt Standard Assumption JSON': If(
                                    locIsFinancialCloseDateStandard,
                                    JSON([{FinancialCloseDate: true}])
                                ),
                                UniqueKeyString: locSeniorDebtUniqueKeyToSave
                            }
                        )
                    }
                );
                Concurrent(
                    If(
                        rad_SeniorDebt_Data_RepaymentProfile.Selected.Value = 'Repayment Profile'.Individual,
                        RemoveIf(
                            'Financing Inputs Repayment Amounts',
                            'Financing Input'.'Financing Input' = locSelectedSeniorDebtTranche.'Financing Input' && !(Value('Repayment Year') in colRepaymentProfileAmount.Year)
                        );
                        ForAll(
                            colRepaymentProfileAmount As Item,
                            Patch(
                                'Financing Inputs Repayment Amounts',
                                If(
                                    IsBlank(Item.RepaymentAmountRecord),
                                    Defaults('Financing Inputs Repayment Amounts'),
                                    Item.RepaymentAmountRecord
                                ),
                                {
                                    Name: $"{Item.Year} - Value",
                                    'Repayment Amount': Value(Item.Value),
                                    'Repayment Year': Text(Item.Year),
                                    'Financing Category': LookUp(
                                        colFinancingCategories,
                                        Order = 3
                                    ),
                                    'Financing Input': locSelectedSeniorDebtTranche,
                                    Project: gblRecordSelectedProject,
                                    'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                                }
                            )
                        ),
                        RemoveIf(
                            'Financing Inputs Repayment Amounts',
                            'Financing Input'.'Financing Input' = locSelectedSeniorDebtTranche.'Financing Input'
                        )
                    ),
                    If(
                        And(
                            CountIf(
                                colStepUpBankMargins,
                                true
                            ) > 0,
                            tgl_SeniorDebtData_Step_Up_Bank_Margin.Checked
                        ),
                        ForAll(
                            colStepUpBankMargins As Item,
                            Patch(
                                'Financing Input Step Up margins',
                                With(
                                    {
                                        locThisItem: LookUp(
                                            colStepUpMarginInProject,
                                            Order = Item.Id && 'Financing Input'.'Financing Input' = locSelectedSeniorDebtTranche.'Financing Input'
                                        )
                                    },
                                    If(
                                        IsBlank(locThisItem),
                                        Defaults('Financing Input Step Up margins'),
                                        locThisItem
                                    )
                                ),
                                With(
                                    {
                                        locLastOne: LookUp(
                                            colStepUpBankMargins,
                                            Id = If(
                                                Item.Id = 1,
                                                1,
                                                Item.Id - 1
                                            )
                                        )
                                    },
                                    {
                                        Name: $"{Item.DurationYY.Value} - Value",
                                        Duration: If(
                                            Item.Id = 1,
                                            Item.DurationYY.Value,
                                            Abs(locLastOne.DurationYY.Value - Item.DurationYY.Value)
                                        ),
                                        'Margin ': Value(Item.Margin),
                                        Project: gblRecordSelectedProject,
                                        'Financing Category': LookUp(
                                            colFinancingCategories,
                                            Order = 3
                                        ),
                                        'Financing Input': locSelectedSeniorDebtTranche,
                                        'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)',
                                        'Start Year': If(
                                            Item.Id = 1,
                                            1,
                                            locLastOne.DurationYY.Value
                                        ),
                                        Order: Item.Id
                                    }
                                )
                            )
                        ),
                        RemoveIf(
                            'Financing Input Step Up margins',
                            'Financing Input'.'Financing Input' = locSelectedSeniorDebtTranche.'Financing Input'
                        )
                    )
                );
                Concurrent(
                    ClearCollect(
                        colFinancingInputInProject,
                        Filter(
                            'Financing Inputs',
                            Project.Project = gblRecordSelectedProject.Project
                        )
                    ),
                    ClearCollect(
                        colRepaymentAmountInProject,
                        Filter(
                            'Financing Inputs Repayment Amounts',
                            Project.Project = gblRecordSelectedProject.Project
                        )
                    ),
                    ClearCollect(
                        colStepUpMarginInProject,
                        Filter(
                            'Financing Input Step Up margins',
                            Project.Project = gblRecordSelectedProject.Project
                        )
                    )
                );
                UpdateContext(
                    {
                        locIsVisibleRightPanelSeniorDebtForm: false,
                        locLoadingSpinnerInformationText: "",
                        locIsVisibleLoadingSpinner: false,
                        locSelectedSeniorDebtTranche: Blank()
                    }
                );
                Select(btn_GeneralData_RightPanel_SeniorDebt_Form_Button_Reset_1);
                UpdateContext({locIsSavingSeniorDebtTranche: false}),
                Notify(
                    "Error while saving Senior Debt tranche: " & FirstError.Message,
                    NotificationType.Error
                );
                UpdateContext(
                    {
                        locIsSavingSeniorDebtTranche: false,
                        locLoadingSpinnerInformationText: "",
                        locIsVisibleLoadingSpinner: false,
                        locIsVisibleRightPanelSeniorDebtForm: false
                    }
                );
                Select(btn_GeneralData_RightPanel_SeniorDebt_Form_Button_Reset_1)
            )
        )
    )
)

